<script lang="ts">import { uploadFeature } from '@fex/components-core/upload/features/upload'; import type { UploadFeatureApi } from '@fex/components-core/upload/types'; import { UploadRoot, UploadTrigger, createUpload } from '@fex/components-svelte/primitive/upload'; import Button from '@fex/components-svelte/ui/button'; import { uploadBody, uploadServerUrl } from './api'; import DemoList from './demo-list.svelte'; import DemoSection from './demo-section.svelte'; const upload = createUpload({ multiple: true, autoUpload: false, features: [uploadFeature({ request: ({ file, signal, onProgress }) => uploadBody(`${uploadServerUrl}/upload`, file, { fileName: file.name, signal, onProgress }) })] })</script>
<DemoSection title="多文件手动上传" description="一次选择多个文件，可逐个上传，也可以手动启动整个文件队列。"><UploadRoot controller={upload}><div class="flex gap-space-sm"><UploadTrigger>{#snippet children(value)}<Button {...value.props}>选择多个文件</Button>{/snippet}</UploadTrigger><Button variant="outline" onclick={() => void upload.getFeature<UploadFeatureApi>('upload')?.startAll()}>全部上传</Button></div><DemoList /></UploadRoot></DemoSection>
